/* RO onboarding and counter workflow. Local demonstration; no server identity or payments. */
const iconPaths={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',operations:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v4m8-4v4M4 11h16m-11 4h6m-6 3h4"/>',scan:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M7 8v8m3-8v8m4-8v8m3-8v8M2 12h20"/>',camera:'<path d="M4 6h4l2-3h4l2 3h4a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1Z"/><circle cx="12" cy="12" r="4"/>',review:'<path d="M9 4H5v17h14V4h-4M9 3h6v4H9zM8 13l2 2 5-5m-7 8h8"/>',team:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-16a3 3 0 0 1 0 6m1 4a5 5 0 0 1 3 5"/>',reports:'<path d="M5 3h10l4 4v14H5zM14 3v5h5M8 17v-4m4 4v-7m4 7v-2"/>',plans:'<rect x="2" y="5" width="20" height="15" rx="3"/><path d="M2 10h20M6 15h4m7 1h1"/>',settings:'<path d="m9 3-.6 3-2.7 1-2.6-1.3-2 3.5L3.4 11v3L1 16l2 3.5 3-1 2.5 1L9 22h4l1-2.5 2.5-1 3 1 2-3.5-2.4-2v-3l2.3-1.8-2-3.5L17 7l-2.5-1L14 3z" transform="translate(1 -1) scale(.92)"/><circle cx="12" cy="12" r="3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="M18 6H6v12M6 6l12 12"/>',bell:'<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5zm5 4h4"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',logout:'<path d="M9 3H4v18h5m6-15 6 6-6 6M8 12h13"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>'};
function icon(name,cls=''){return `<svg class="ro-icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.operations}</svg>`}
const packages=[{name:'الأساسية',price:299,branches:1,counters:2,days:15},{name:'الأعمال',price:599,branches:2,counters:5,days:15},{name:'المتقدمة',price:1299,branches:5,counters:12,days:30},{name:'المؤسسات',price:2499,branches:999,counters:999,days:365}];
db.requests??=[];db.demoAccounts??=[];let chosenPlan=Number(sessionStorage.getItem('ro-plan')||1);if(!packages[chosenPlan])chosenPlan=1;let authMode='signup',currentAccount=sessionStorage.getItem('ro-account')||null,requestFilter='all';
const baseLanding=landing,baseSettings=settings,baseDetail=detail;
function packageCards(){return `<div class="plans public-plans">${packages.map((p,i)=>`<article class="pricing ${i===1?'selected':''}"><span class="badge">${i===1?'للأعمال المتنامية':'الباقة '+(i+1)}</span><h3>${p.name}</h3><div class="price">${p.price.toLocaleString('en')} <small>ر.س</small></div><p class="muted">لمدة ${p.days} يومًا</p><ul><li>${icon('check')} ${p.branches} ${p.branches===1?'فرع':'فروع'}</li><li>${icon('team')} ${p.counters} موظفي جرد</li><li>${icon('scan')} جرد مفتوح أو بمرجع</li><li>${icon('reports')} مراجعة النتائج والتقارير</li></ul><button class="${i===1?'primary':''}" onclick="choosePlan(${i})">اختيار الباقة ${icon('arrow')}</button></article>`).join('')}</div>`}
landing=function(){let html=baseLanding();html=html.replace('<a href="#questions">الأسئلة الشائعة</a>','<a href="#packages">الباقات</a><a href="#questions">الأسئلة الشائعة</a>');if(account())html=html.replace('<button onclick="go(\'dashboard\')">دخول النسخة التجريبية ↖</button>', '<button onclick="go(\'checkout\')">متابعة طلب الاشتراك ↖</button>');html=html.replace('<section class="marketing-section" id="questions">',`<section class="marketing-section" id="packages"><div class="section-heading"><h2><mark>باقة على قدّ شغلك.</mark></h2><p>اختر باقتك، سجّل حساب الشركة، ثم أرفق إيصال التحويل للمراجعة.</p><span>03 / الباقات</span></div><p class="muted">طلب الاشتراك هنا تجريبي ومحلي. لا تُجرِ تحويلًا ماليًا بناءً على هذه النسخة. حدود السجلات والعمليات ستُحدد قبل الإطلاق.</p>${packageCards()}</section><section class="marketing-section" id="questions">`);return html};
plans=function(){return head('اختر باقة شركتك','اختر الباقة للانتقال إلى التسجيل وطلب التفعيل.')+`<div class="warning">مسار اشتراك تجريبي على هذا المتصفح. لا يتضمن دفعًا إلكترونيًا أو تفعيلًا حقيقيًا.</div>`+packageCards()};
function choosePlan(i){if(!packages[i])return;chosenPlan=i;sessionStorage.setItem('ro-plan',String(i));if(currentAccount&&db.demoAccounts.some(a=>a.id===currentAccount))go('checkout');else{authMode='signup';go('auth')}}
function authPage(){return `<div class="enrollment"><button class="link" onclick="go('landing')">العودة للرئيسية ←</button><div class="enroll-layout"><section class="panel enroll-form"><span class="eyebrow">RO / COMPANY ACCOUNT</span><h1>${authMode==='signup'?'بداية مرتبة لشركتك.':'مرحبًا بعودتك.'}</h1><p class="muted">${authMode==='signup'?'أنشئ حساب الشركة، ثم أكمل طلب الاشتراك.':'سجّل الدخول بحسابك التجريبي على هذا الجهاز.'}</p><div class="auth-tabs"><button class="${authMode==='signup'?'active':''}" onclick="authMode='signup';render()">حساب جديد</button><button class="${authMode==='login'?'active':''}" onclick="authMode='login';render()">تسجيل الدخول</button></div><div class="warning">حساب تجريبي محفوظ على هذا المتصفح فقط. استخدم بيانات اختبار وكلمة مرور غير مستخدمة في حساباتك الحقيقية.</div><form id="authForm">${authMode==='signup'?'<label class="field">اسم الشركة<input name="company" required maxlength="100" autocomplete="organization" placeholder="مثال: شركة الأفق"></label>':''}<label class="field">البريد الإلكتروني<input type="email" name="email" required maxlength="160" dir="ltr" autocomplete="username" placeholder="name@company.com"></label><label class="field">كلمة المرور<input name="password" type="password" required minlength="8" maxlength="128" autocomplete="${authMode==='signup'?'new-password':'current-password'}" placeholder="8 أحرف على الأقل"></label><p id="authError" class="form-error" role="alert"></p><button class="primary wide" type="submit">${authMode==='signup'?'إنشاء الحساب والمتابعة':'دخول ومتابعة'} ${icon('arrow')}</button></form></section>${planSummary()}</div></div>`}
function planSummary(){let p=packages[chosenPlan];return `<aside class="order-summary"><span class="badge">الباقة المختارة</span><h2>${p.name}</h2><div class="price">${p.price} <small>ر.س</small></div><p>لمدة ${p.days} يومًا</p><hr><p>${icon('team')} ${p.counters} موظفي جرد</p><p>${icon('operations')} ${p.branches} فروع</p><p>${icon('review')} التفعيل بعد مراجعة الإيصال</p><button onclick="go('plans')">تغيير الباقة</button><small>الأسعار من إعدادات RO الحالية، ومعروضة للتجربة.</small></aside>`}
async function passwordDigest(password,salt){if(!crypto.subtle)throw Error('التسجيل التجريبي يحتاج اتصال HTTPS. افتح رابط RO المنشور.');const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bytes=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:210000,hash:'SHA-256'},key,256);return Array.from(new Uint8Array(bytes),v=>v.toString(16).padStart(2,'0')).join('')}
function attachAuth(){const form=$('#authForm');if(!form)return;form.onsubmit=async e=>{e.preventDefault();let button=form.querySelector('button[type=submit]');button.disabled=true;$('#authError').textContent='';try{const f=new FormData(form),email=f.get('email').trim().toLowerCase(),password=f.get('password');let account=db.demoAccounts.find(a=>a.email===email);if(authMode==='signup'){if(account)throw Error('هذا البريد مسجل على المتصفح. اختر تسجيل الدخول.');let company=f.get('company').trim();if(!company)throw Error('أدخل اسم الشركة');let salt=newId(),hash=await passwordDigest(password,salt);account={id:newId(),company,email,salt,hash};db.demoAccounts.push(account);save()}else{if(!account||await passwordDigest(password,account.salt)!==account.hash)throw Error('البريد الإلكتروني أو كلمة المرور غير صحيحة.')}form.reset();currentAccount=account.id;sessionStorage.setItem('ro-account',account.id);go('checkout')}catch(err){$('#authError').textContent=err.message}finally{button.disabled=false}}}
function account(){return db.demoAccounts.find(a=>a.id===currentAccount)}
function checkoutPage(){let a=account();if(!a){authMode='login';return authPage()}let last=db.requests.find(r=>r.accountId===a.id);if(last)return pendingPage(last);return `<div class="enrollment"><button class="link" onclick="go('plans')">العودة للباقات ←</button><div class="enroll-layout"><section class="panel enroll-form"><span class="eyebrow">RO / SUBSCRIPTION REQUEST</span><h1>خطوة أخيرة، ونراجع طلبك.</h1><p class="muted">${esc(a.company)} · ${esc(a.email)}</p><div class="warning">نموذج تجريبي: لا توجد بيانات تحويل معتمدة بعد. أرفق ملف اختبار فقط؛ الطلب لن يصل إلى خادم أو مسؤول حقيقي.</div><form id="checkoutForm"><label class="field">إيصال الدفع<input type="file" name="receipt" accept="image/jpeg,image/png,application/pdf" required><small>JPG أو PNG أو PDF · بحد أقصى 5 ميجابايت</small></label><label class="field">رقم مرجع التحويل <small>اختياري</small><input name="transferRef" maxlength="100" placeholder="رقم العملية في الإيصال"></label><label class="field">ملاحظات <small>اختياري</small><textarea name="notes" maxlength="500" rows="3"></textarea></label><p id="checkoutError" class="form-error" role="alert"></p><button class="primary wide" type="submit">${icon('upload')} إرسال طلب التفعيل التجريبي</button></form><button class="link signout" onclick="logoutAccount()">تسجيل الخروج</button></section>${planSummary()}</div></div>`}
function receiptDB(){return new Promise((resolve,reject)=>{let r=indexedDB.open('ro-demo-receipts',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('تعذر فتح التخزين المحلي للإيصال'))})}
async function storeReceipt(id,file){let database=await receiptDB();try{await new Promise((resolve,reject)=>{let tx=database.transaction('files','readwrite');tx.objectStore('files').put(file,id);tx.oncomplete=resolve;tx.onerror=()=>reject(Error('تعذر حفظ الإيصال؛ تحقق من مساحة التخزين'));tx.onabort=tx.onerror})}finally{database.close()}}
async function readReceipt(id){let database=await receiptDB();try{return await new Promise((resolve,reject)=>{let req=database.transaction('files').objectStore('files').get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(Error('تعذر قراءة الإيصال'))})}finally{database.close()}}
async function validReceipt(file){if(!file||!file.size)throw Error('أرفق إيصال الدفع');if(file.size>5*1024*1024)throw Error('حجم الإيصال يتجاوز 5 ميجابايت');const b=new Uint8Array(await file.slice(0,8).arrayBuffer());const png=b[0]===137&&b[1]===80&&b[2]===78&&b[3]===71;const jpeg=b[0]===255&&b[1]===216&&b[2]===255;const pdf=b[0]===37&&b[1]===80&&b[2]===68&&b[3]===70&&b[4]===45;if(!((png&&file.type==='image/png')||(jpeg&&file.type==='image/jpeg')||(pdf&&file.type==='application/pdf')))throw Error('ارفع صورة JPG أو PNG أو ملف PDF صالحًا')}
function attachCheckout(){let form=$('#checkoutForm');if(!form)return;form.onsubmit=async e=>{e.preventDefault();let button=form.querySelector('button[type=submit]');button.disabled=true;try{let a=account();if(!a)throw Error('سجل الدخول أولًا');if(db.requests.some(r=>r.accountId===a.id&&r.status==='pending')){go('checkout');return}let f=new FormData(form),file=f.get('receipt');await validReceipt(file);let request={id:'REQ-'+newId().slice(0,8),accountId:a.id,company:a.company,email:a.email,plan:chosenPlan,status:'pending',transferRef:f.get('transferRef').trim(),notes:f.get('notes').trim(),fileName:file.name,created:new Date().toISOString()};await storeReceipt(request.id,file);db.requests.unshift(request);save('استلام طلب اشتراك تجريبي '+request.id);go('checkout')}catch(err){$('#checkoutError').textContent=err.message}finally{button.disabled=false}}}
function pendingPage(r){return `<div class="request-state panel"><div class="state-icon">${icon(r.status==='pending'?'clock':r.status==='approved'?'check':'close')}</div><span class="eyebrow">${esc(r.id)}</span><h1>${r.status==='pending'?'طلبك قيد المعالجة':r.status==='approved'?'تم قبول طلبك التجريبي':'يحتاج طلبك إلى تعديل'}</h1><p>${r.status==='pending'?'تم حفظ الطلب والإيصال على هذا الجهاز. يمكنك متابعة القرار هنا بعد مراجعته من شاشة السوبر أدمن التجريبية.':r.status==='approved'?'تم تحديث حالة الطلب محليًا. إنشاء بيئة الشركة والتفعيل الفعلي ينتظران ربط الخادم.':esc(r.reason||'راجع ملاحظات المسؤول وأرسل طلبًا جديدًا.')}</p><dl><div><dt>الشركة</dt><dd>${esc(r.company)}</dd></div><div><dt>الباقة</dt><dd>${packages[r.plan].name}</dd></div><div><dt>المبلغ</dt><dd>${packages[r.plan].price} ر.س</dd></div><div><dt>الحالة</dt><dd><span class="badge ${r.status==='pending'?'amber':''}">${statusName(r.status)}</span></dd></div></dl><div class="warning">هذه الحالة محلية للتجربة؛ لم يتم إرسال الإيصال أو إنشاء اشتراك فعلي.</div><button onclick="go('plans')">الباقات</button> <button onclick="logoutAccount()">تسجيل الخروج</button></div>`}
function logoutAccount(){currentAccount=null;sessionStorage.removeItem('ro-account');go('landing')}
function statusName(s){return ({pending:'قيد المعالجة',approved:'مقبول',rejected:'يحتاج تعديل'})[s]||s}
function adminPage(){let requests=db.requests.filter(r=>requestFilter==='all'||r.status===requestFilter);return head('طلبات الاشتراك','لوحة السوبر أدمن التجريبية · الطلبات المحفوظة على هذا المتصفح فقط.','<button onclick="go(\'settings\')">العودة للإعدادات</button>')+`<div class="warning">هذه معاينة محلية وليست حساب سوبر أدمن محميًا. الموافقة تغيّر حالة الطلب فقط ولا تفعّل باقة حقيقية.</div><div class="stats">${[['pending','قيد المعالجة'],['approved','مقبولة'],['rejected','تحتاج تعديل']].map(([s,t])=>`<div class="stat"><div class="stat-top">${t}${icon('plans')}</div><strong>${db.requests.filter(r=>r.status===s).length}</strong></div>`).join('')}</div><section class="panel"><div class="toolbar"><select aria-label="حالة الطلب" onchange="requestFilter=this.value;render()">${[['all','كل الطلبات'],['pending','قيد المعالجة'],['approved','مقبول'],['rejected','يحتاج تعديل']].map(([v,t])=>`<option value="${v}" ${requestFilter===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>الشركة</th><th>الباقة / المبلغ</th><th>الإيصال</th><th>الحالة</th><th>المراجعة</th></tr></thead><tbody>${requests.map(r=>`<tr><td><b>${esc(r.company)}</b><small>${esc(r.email)} · ${esc(r.id)}</small></td><td>${packages[r.plan].name}<small>${packages[r.plan].price} ر.س</small></td><td><button onclick="downloadReceipt('${r.id}')">${icon('reports')} تنزيل الإيصال</button><small>${esc(r.fileName)}</small></td><td><span class="badge ${r.status==='pending'?'amber':'gray'}">${statusName(r.status)}</span></td><td><button onclick="reviewRequest('${r.id}')">مراجعة الطلب ${icon('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">لا توجد طلبات. ابدأ باختيار باقة من صفحة الهبوط.</td></tr>'}</tbody></table></div></section>`}
async function downloadReceipt(id){try{let file=await readReceipt(id);if(!file)return toast('الإيصال غير موجود على هذا الجهاز');const url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download='RO-receipt-'+id+(file.type==='application/pdf'?'.pdf':file.type==='image/png'?'.png':'.jpg');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(err){toast(err.message)}}
function reviewRequest(id){let r=db.requests.find(r=>r.id===id);if(!r||db.role!=='company')return;modal(`<h2>مراجعة ${esc(r.id)}</h2><p>${esc(r.company)} · ${packages[r.plan].name} · ${packages[r.plan].price} ر.س</p><p>مرجع التحويل: ${esc(r.transferRef)||'—'}</p><p>ملاحظات العميل: ${esc(r.notes)||'—'}</p>${r.status==='pending'?`<label class="field">القرار<select name="decision"><option value="approved">قبول الطلب التجريبي</option><option value="rejected">طلب تعديل / رفض</option></select></label><label class="field">ملاحظات المراجعة<textarea name="reason" maxlength="500"></textarea></label>${modalButtons('حفظ القرار')}`:`<p>الحالة: ${statusName(r.status)}</p><p>${esc(r.reason)}</p><button type="button" onclick="closeDialog()">إغلاق</button>`}`,f=>{if(r.status!=='pending')return;let reason=f.get('reason').trim();if(f.get('decision')==='rejected'&&!reason)throw Error('اكتب سبب طلب التعديل');r.status=f.get('decision');r.reason=reason;r.reviewedAt=new Date().toISOString();save('مراجعة طلب الاشتراك '+r.id);closeDialog();render();toast('تم تحديث حالة الطلب محليًا')})}
settings=function(){return baseSettings()+`<section class="panel"><div class="scan"><h2>${icon('plans')} السوبر أدمن</h2><p class="muted">معاينة طلبات الاشتراك وملفات الإيصالات المحفوظة على هذا الجهاز.</p><button onclick="go('admin')">فتح طلبات الاشتراك</button></div></section>`};
function employeeHome(){let os=visibleOps().filter(o=>o.status==='open');return `<div class="employee-workspace"><div class="employee-header"><div class="wordmark">RO<span>✳</span></div><span class="badge">موظف الجرد · ${esc(user(activeUser()))}</span><button class="icon" aria-label="الخروج من المعاينة" onclick="exitEmployee()">${icon('logout')}</button></div><h1>عمليات الجرد المسندة لك</h1><p class="muted">اختر عمليتك وابدأ قراءة الباركود.</p><div class="assigned-list">${os.map(o=>`<button class="assigned-operation" onclick="enterCount('${o.id}')"><div class="assigned-icon">${icon('scan')}</div><div><b>${esc(o.name)}</b><small>${esc(o.branch)} · ${esc(o.id)}</small><span class="badge">قيد التنفيذ</span></div>${icon('arrow')}</button>`).join('')||'<div class="panel empty">لا توجد عمليات مفتوحة مسندة لك.</div>'}</div><p class="employee-demo">معاينة محلية · الدخول الفعلي وربط الجهاز ينتظران الخادم</p></div>`}
function exitEmployee(){db.role='company';save();go('settings')}function enterCount(id){if(!visibleOps().some(o=>o.id===id&&o.status==='open'))return;selected=id;go('scan')}
let cameraStream=null,scanControls=null,cameraGeneration=0,cameraPending=false,scanLocked=false,lastBarcodeAt=0;
function stopCamera(){scanLocked=false;cameraGeneration++;cameraPending=false;try{scanControls?.stop()}catch{}scanControls=null;if(cameraStream)cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null;const video=$('#barcodeVideo');if(video){video.pause();video.srcObject=null}const area=$('#cameraArea');if(area)area.hidden=true;const start=$('#cameraStart');if(start)start.disabled=false}
async function startCamera(){if(cameraPending||cameraStream)return;let status=$('#cameraStatus');if(!navigator.mediaDevices?.getUserMedia){status.textContent='الكاميرا تحتاج رابط HTTPS وصلاحية المتصفح. افتح رابط RO المنشور، أو أدخل الباركود يدويًا.';return}cameraPending=true;const generation=++cameraGeneration;$('#cameraStart').disabled=true;status.textContent='جاري طلب صلاحية الكاميرا…';try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});if(generation!==cameraGeneration){stream.getTracks().forEach(t=>t.stop());return}cameraStream=stream;const video=$('#barcodeVideo');$('#cameraArea').hidden=false;status.textContent='الماسح يعمل باستمرار. وجّه الباركود، ثم أدخل الكمية واحفظها.';if(!window.ZXingBrowser)throw Error('تعذر تحميل قارئ الباركود. أعد فتح الصفحة.');const reader=new ZXingBrowser.BrowserMultiFormatReader();const controls=await reader.decodeFromStream(stream,video,(result,error,c)=>{if(generation!==cameraGeneration)return;if(result){const code=result.getText();if(!code||code.length>100)return;if(scanLocked||Date.now()-lastBarcodeAt<1400)return;scanLocked=true;lastBarcodeAt=Date.now();$('#scanForm').elements.barcode.value=code;$('#cameraStatus').textContent='تمت القراءة: '+code+' — أدخل الكمية واحفظها. الكاميرا مستمرة.';$('#scanForm').elements.qty.focus();navigator.vibrate?.(80)}});if(generation!==cameraGeneration){controls.stop();return}scanControls=controls;cameraPending=false}catch(err){if(generation!==cameraGeneration)return;stopCamera();status.textContent=err.name==='NotAllowedError'?'لم تسمح بالكاميرا. يمكنك تفعيل الصلاحية من المتصفح أو إدخال الباركود يدويًا.':err.name==='NotFoundError'?'لا توجد كاميرا متاحة على هذا الجهاز.':err.message||'تعذر تشغيل الكاميرا. جرّب الإدخال اليدوي.'}}
window.addEventListener('pagehide',stopCamera);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopCamera()});
function quickQuantity(n,add=false){let field=$('#scanForm')?.elements.qty;if(!field)return;let v=add?Number(field.value||0)+n:n;if(Number.isSafeInteger(v)&&v>=0&&v<=1e9)field.value=v;else toast('الكمية خارج النطاق المسموح')}
scanPage=function(){const employee=db.role==='employee',os=visibleOps().filter(o=>o.status==='open');if(!os.length)return employeeHome();if(!os.some(o=>o.id===selected)){if(employee)return employeeHome();selected=os[0].id}const o=op(selected);return `<div class="${employee?'employee-workspace':''}">${employee?`<div class="employee-header"><button onclick="go('operations')">${icon('arrow')} العمليات</button><span class="badge">${esc(user(activeUser()))}</span></div>`:''}${head(employee?esc(o.name):'اقرأ الباركود. وأدخل الكمية.',employee?esc(o.branch):'افتح الكاميرا أو استخدم قارئ الباركود، ثم سجّل العدد.')}<section class="panel scan counter-panel"><form id="scanForm">${employee?`<input type="hidden" name="operation" value="${esc(o.id)}">`:`<label class="field">عملية الجرد<select name="operation">${os.map(x=>`<option value="${x.id}" ${x.id===selected?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label class="field">تسجيل باسم الموظف<select name="employee">${db.users.filter(u=>u.role==='employee'&&o.staff.includes(u.id)).map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select></label>`}<div class="camera-box"><button id="cameraStart" class="camera-launch" type="button" onclick="startCamera()">${icon('camera')} فتح كاميرا الجوال لمسح الباركود</button><div id="cameraArea" hidden><div class="video-frame"><video id="barcodeVideo" playsinline muted></video><div class="scan-guide"></div></div><button type="button" onclick="stopCamera()">${icon('close')} إيقاف الكاميرا</button></div><p id="cameraStatus" role="status" class="muted">تُطلب صلاحية الكاميرا عند الضغط فقط. الصور لا تُرفع للخادم.</p></div><label class="field">رقم الباركود<input name="barcode" required maxlength="100" autocomplete="off" inputmode="numeric" dir="ltr" placeholder="رقم الباركود يظهر هنا"></label><label class="field quantity-field">الكمية<input name="qty" aria-label="الكمية" type="number" min="0" max="1000000000" step="1" value="1" required inputmode="numeric"></label><div class="quantity-shortcuts"><button type="button" onclick="quickQuantity(6)">6 <small>حبات</small></button><button type="button" onclick="quickQuantity(12)">12 <small>حبة</small></button><button type="button" onclick="quickQuantity(24)">24 <small>حبة</small></button><button type="button" class="plus-one" onclick="quickQuantity(1,true)" dir="ltr">+1</button></div><p class="muted shortcut-note">6 و12 و24 تحدد الكمية، و‎+1 يضيف حبة إلى العدد الحالي.</p><label class="field">الرف / الموقع<input name="location" required value="A1" maxlength="80"></label><label class="field">ملاحظات <small>اختياري</small><textarea name="note" rows="2" maxlength="500"></textarea></label><button class="primary wide save-count">${icon('check')} حفظ الكمية والانتقال للصنف التالي</button></form><p class="employee-demo">الحفظ محلي في النسخة التجريبية.</p></section></div>`};
render=function(){db.requests??=[];db.demoAccounts??=[];stopCamera();let employee=db.role==='employee';let publicPages=['landing','auth','checkout'];if(employee&&!publicPages.includes(page)&&!['operations','scan'].includes(page))page='operations';let available=employee?['operations','scan']:['dashboard','operations','scan',...(canReview()?['review','team','reports']:[]),...(canManage()?['plans']:[]),'settings'];if(!available.includes(page)&&!['detail','landing','auth','checkout','admin','platform','addons'].includes(page))page=employee?'operations':'dashboard';if(['admin','platform'].includes(page)&&!canManage())page='operations';document.body.dataset.page=page;document.body.dataset.role=db.role;document.body.classList.toggle('public-flow',publicPages.includes(page));$('#nav').innerHTML=available.map(p=>`<button class="${page===p?'active':''}" onclick="go('${p}')"><span>${icon(p)}</span><em style="font-style:normal">${labels[p]}</em>${p==='review'&&groups().some(([k])=>!db.resolutions[k])?'<b>'+groups().filter(([k])=>!db.resolutions[k]).length+'</b>':''}</button>`).join('');$('#roleLabel').textContent=roles[db.role];$('#breadcrumb').textContent=labels[page]||({auth:'حساب الشركة',checkout:'طلب الاشتراك',admin:'السوبر أدمن'})[page]||'تفاصيل العملية';const views={dashboard,operations:employee?employeeHome:operations,scan:scanPage,review:reviewPage,team,reports,plans,settings,landing,detail:employee?scanPage:detailPage,auth:authPage,checkout:checkoutPage,admin:adminPage,platform:()=>platformPage(),addons:()=>addonsPage()};$('#app').innerHTML=(views[page]||dashboard)();attachScan();attachAuth();attachCheckout();if(db.role==='employee'&&page==='scan'&&$('#barcodeVideo'))startCamera();$('#dialog').addEventListener('close',()=>{}, {once:true});document.querySelectorAll('.stat-top>i').forEach((el,i)=>el.innerHTML=icon(['operations','scan','reports','clock'][i%4]));document.querySelectorAll('.activity-item>i').forEach(el=>el.innerHTML=icon('check'));document.querySelectorAll('.barcode b,.floating-ticket>b').forEach(el=>el.innerHTML=icon('scan'));document.querySelectorAll('.hero-tag').forEach(el=>el.innerHTML=icon('check')+' كل وحدة محسوبة');document.querySelectorAll('.round-arrow').forEach(el=>el.innerHTML=icon('arrow'));document.querySelectorAll('header .icon').forEach(el=>el.innerHTML=icon('bell'));document.querySelectorAll('.profile button').forEach(el=>el.innerHTML=icon('settings'));document.querySelectorAll('.dots').forEach(el=>{el.innerHTML=icon('arrow');el.setAttribute('aria-label','عرض التفاصيل')});};
render();

window.addEventListener('storage',e=>{if(e.key!=='ro-demo-v1')return;try{const latest=JSON.parse(e.newValue);db.requests=latest.requests||[];db.demoAccounts=latest.demoAccounts||[];if(page==='admin'||(page==='checkout'&&!$('#checkoutForm')))render()}catch{}});
